async function single(){try{resume.value=(await accountRequest('room')).room}catch{notice.value='无法确认本场状态，请先重试或返回朋友房。';return}if(resume.value?.active){if(!confirm('你有未结束的朋友房，进入单机将暂离并托管，席位与积分保留。是否继续？'))return;try{await accountRequest('away',{})}catch{notice.value='暂离未确认，请先返回本场处理。';return}}location.href='?scene=play'}
</script>
